#include "PythonParity.hpp"
namespace iso_tool {std::string LanguageOf(const std::filesystem::path&p){auto e=p.extension().string();if(e==".py")return"python";if(e==".cpp"||e==".cc"||e==".cxx")return"cpp";if(e==".c")return"c";if(e==".cs")return"csharp";if(e==".java")return"java";if(e==".asm"||e==".s")return"assembly";return"other";}std::vector<SourceFile>ScanPythonParity(const std::filesystem::path&root){std::vector<SourceFile>r;if(!std::filesystem::exists(root))return r;for(auto const&e:std::filesystem::recursive_directory_iterator(root))if(e.is_regular_file()&&LanguageOf(e.path())=="python")r.push_back({e.path(),"python"});return r;}}
